  "lim.tans_examples_html":"Ejemplos: <code>3</code>, <code>0</code>, <code>inf</code>, <code>-inf</code>, <code>%pi</code>, <code>1/2</code>",
  "lim.fbgen_auto_desc":   "La corrección (fórmula, valor) se genera automáticamente según los ajustes seleccionados en «Config».",
  "lim.banniere":          "Límites",
  "lim.calc_limite":       "Calcular el límite:",
  "lim.taper_inf_ou_moins_inf": "Escribe <code>inf</code> para \\(+\\infty\\) o <code>-inf</code> para \\(-\\infty\\).",
  "lim.taper_inf":         "Escribe <code>inf</code> para \\(+\\infty\\).",
  "lim.taper_moins_inf":   "Escribe <code>-inf</code> para \\(-\\infty\\).",
  "lim.calc_limite_indetermination": "Calcular (eliminando la indeterminación):",
  "lim.calc_limite_droite": "Calcular el límite por la derecha:",
  "lim.calc_limite_gauche": "Calcular el límite por la izquierda:",
  "lim.fb_wrong_fixe":     "<strong>Método</strong>: intentar primero la sustitución directa. Si se obtiene una forma indeterminada (0/0, ∞/∞, ∞−∞...), factorizar o simplificar la expresión antes de volver a calcular el límite.<br>Respuesta esperada: {@{tavar}@}.",
  "lim.fbgen_fixe":        "El límite solicitado es {@{tavar}@}. Comprueba la sustitución directa y, en caso de forma indeterminada, factoriza o simplifica antes de llegar a una conclusión.",
  "lim.fb_wrong_plus_inf": "<strong>Método</strong>: para un límite en \\(+\\infty\\) de un cociente de polinomios, se comparan los grados del numerador y del denominador (lo que equivale a sacar en factor común la potencia dominante de ambos lados).<br>En este caso, el numerador \\({@{numvar}@}\\) es de grado {@{degnvar}@} (coeficiente dominante {@{lcnvar}@}), y el denominador \\({@{denvar}@}\\) tiene grado {@{degdvar}@} (coeficiente dominante {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; límite 0.<br>• deg(num) = deg(den) &rarr; límite = relación entre los coeficientes dominantes.<br>• deg(num) &gt; deg(den) &rarr; límite infinito.<br>Conclusión: el límite es {@{tavar}@}.",
  "lim.fbgen_plus_inf":    "\\(\\displaystyle\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\) : numerador de grado {@{degnvar}@} (coeficiente dominante {@{lcnvar}@}), denominador de grado {@{degdvar}@} (coeficiente dominante {@{lcdvar}@}).<br>\\(\\lim_{x\\to+\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_moins_inf":"<strong>Método</strong>: para un límite en \\(-\\infty\\) de un cociente de polinomios, se comparan los grados del numerador y del denominador.<br>En este caso, el numerador \\({@{numvar}@}\\) es de grado {@{degnvar}@} (coeficiente dominante {@{lcnvar}@}), y el denominador \\({@{denvar}@}\\) tiene grado {@{degdvar}@} (coeficiente dominante {@{lcdvar}@}).<br>• deg(num) &lt; deg(den) &rarr; límite 0.<br>• deg(num) = deg(den) &rarr; límite = relación entre los coeficientes dominantes.<br>• deg(num) &gt; deg(den) &rarr; límite 0.<br>Conclusión: el límite es {@{tavar}@}.",
  "lim.fbgen_moins_inf":   "\\(\\displaystyle\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}\\) : numerador de grado {@{degnvar}@} (coeficiente dominante {@{lcnvar}@}), denominador de grado {@{degdvar}@} (coeficiente dominante {@{lcdvar}@}).<br>\\(\\lim_{x\\to-\\infty}\\frac{{@{numvar}@}}{{@{denvar}@}}={@{tavar}@}\\).",
  "lim.fb_wrong_point_fini":"<strong>Método</strong>: tanto el numerador como el denominador se anulan en \\(x={@{avar}@}\\) (forma indeterminada 0/0). Factorizamos \\((x-{@{avar}@})\\) en el numerador: \\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\).<br>Simplificamos utilizando el factor idéntico del denominador: \\(\\frac{(x-{@{avar}@})({@{qvar}@})}{x-{@{avar}@}}={@{qvar}@}\\).<br>Queda por calcular, para \\(x={@{avar}@}\\): {@{tavar}@}.",
  "lim.fbgen_point_fini":  "Factoriza \\((x-{@{avar}@})\\) en el numerador (\\({@{numvar}@}=(x-{@{avar}@})({@{qvar}@})\\)), y luego simplifica con el denominador: queda \\({@{qvar}@}\\).<br>Al sustituir \\(x={@{avar}@}\\), se obtiene \\(\\lim={@{tavar}@}\\).",
  "lim.fb_wrong_droite":   "<strong>Método</strong>: se establece el cambio de variable \\(u=x-{@{avar}@}\\); cuando \\(x\\to{@{avar}@}^+\\), se tiene que \\(u\\to 0^+\\) (u sigue siendo positivo).<br>La expresión se convierte en \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\).<br>Cuando \\(u\\to 0^+\\), \\(\\sqrt{u}\\to 0^+\\), por lo que \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fbgen_droite":      "Si se establece \\(u=x-{@{avar}@}\\to 0^+\\) : la expresión se convierte en \\(\\frac{\\sqrt{u}}{u}=\\frac{1}{\\sqrt{u}}\\to+\\infty\\).",
  "lim.fb_wrong_gauche":   "<strong>Método</strong>: se establece que \\(u={@{avar}@}-x\\); cuando \\(x\\to{@{avar}@}^-\\), se tiene que \\(u\\to 0^+\\), y \\(x-{@{avar}@}=-u\\).<br>La expresión se convierte en \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\).<br>Cuando \\(u\\to 0^+\\), \\(\\frac{1}{\\sqrt{u}}\\to+\\infty\\), por lo que la expresión tiende a \\(-\\infty\\).",
  "lim.fbgen_gauche":      "Si se establece que \\(u={@{avar}@}-x\\= 0^+\\), siendo \\(x-{@{avar}@}=-u\\): la expresión se convierte en \\(\\frac{\\sqrt{u}}{-u}=-\\frac{1}{\\sqrt{u}}\\to-\\infty\\).",

