  "osc.consigne_periode_frequence": "Con ayuda de los cursores (botones <span style=\"color:#a855f7;font-weight:bold;\">■ X</span> y <span style=\"color:#ef4444;font-weight:bold;\">■ Y</span>), mide el periodo \\(T\\) de la tensión <strong>{@ta{X}_type_text@}</strong> y, a continuación, deduce su frecuencia \\(f\\).",
