  "osc.fb_periode_unite_ko": "<strong>Período:</strong> El período que has introducido es incorrecto porque no tiene la unidad adecuada. La unidad esperada, en el sistema SI, era {@teacher_unit_T{X}/2@}.",
  "osc.fb_periode_ok": "<strong>Período:</strong> Tu período es correcto",
  "osc.fb_periode_valeur_ko": "<strong>Período:</strong> El valor numérico o la precisión de tu período son incorrectos.",
  "osc.fb_frequence_unite_ko": "La unidad de tu frecuencia no es una unidad válida. La unidad esperada era: {@teacher_unit_F{X}/2@}.",
  "osc.fb_frequence_ok": "<strong>¡Enhorabuena!</strong> Tu frecuencia es totalmente correcta",
