  "osc.fb_frequence_coherente_trap": "Tu frecuencia es coherente con tu respuesta a lo largo del periodo, pero no era la respuesta esperada.",
  "osc.fb_frequence_incoherente": "Tu frecuencia no tiene sentido en relación con tu respuesta anterior \\( f= \\frac {1}{T} \\)",
  "osc.genfb_reponses_attendues": "🔑 Respuestas esperadas",
  "osc.genfb_q1_periode": "1.º trimestre:",
  "osc.genfb_periode_explanation": "El período es el tiempo que tarda un fenómeno cíclico en repetirse exactamente igual. En esta tensión {@ta{X}_type_text@}, utilizando los controles deslizantes de tiempo, se obtiene T = {@1.0*ta{X}_T@}",
  "osc.genfb_q2_frequence": "P2 Frecuencia:",
  "osc.genfb_frequence_explanation": "La frecuencia es el número de veces que se repite un fenómeno por segundo; se calcula mediante la fórmula \\[ f = \\frac{1}{T} \\]",
  "osc.genfb_frequence_calcul": "Por lo tanto, tenemos que \\[ f= \\frac {1}{ {@1.0*ta{X}_T@} }= {@ta{X}_fq@} \\]",
  "osc.consigne_y_decharge": "Con <span style=\"color:#ef4444;font-weight:bold;\">■ Y</span>, calcula la amplitud de la tensión inicial \\(E\\) (entre el nivel y la línea inferior).",
  "osc.consigne_y_charge": "Con <span style=\"color:#ef4444;font-weight:bold;\">■ Y</span>, calcula la amplitud de la tensión final \\(E\\) (entre el nivel máximo y la línea inferior).",
  "osc.consigne_tau_decharge": "Con <span style=\"color:#a855f7;font-weight:bold;\">■ X</span>, calcula la constante de tiempo \\(\\tau\\) (entre el instante \\(t=0\\) y el punto correspondiente al 36,8 % de \\(E\\)).",
  "osc.consigne_tau_charge": "Con <span style=\"color:#a855f7;font-weight:bold;\">■ X</span>, calcula la constante de tiempo \\(\\tau\\) (entre el instante \\(t=0\\) y el punto correspondiente al 63,2 % de \\(E\\)).",
  "osc.rc_intro": "En el osciloscopio se visualiza la tensión \\(u_C(t)\\) entre los bornes de un condensador durante su {modo}.",
