  "osc.genfb_tension_explanation": "Al medir el nivel de tensión con los cursores Y, se obtiene \\(E\\) = {@ta{X}_E@}.",
  "osc.retard_intro": "Se visualiza la señal del transmisor (Canal A, <span style=\"color:#2563eb;font-weight:bold;\">Azul</span>) y la señal del receptor (Canal B, <span style=\"color:#dc2626;font-weight:bold;\">Rojo</span>).",
