  "osc.fb_retard_trap_demi_periode": "<strong>Retardo:</strong> Has calculado la mitad del periodo de la señal (\\(T/2\\)) en lugar del desfase temporal entre las ráfagas.",
  "osc.fb_retard_valeur_ko": "<strong>Retardo:</strong> El valor numérico o la precisión son incorrectos. Coloca un cursor en el inicio de la ráfaga azul (emisión) y el otro en el inicio de la ráfaga roja (recepción).",
  "osc.genfb_q1_frequence_retard": "P1 Frecuencia:",
  "osc.genfb_frequence_retard_explanation": "Al medir UN periodo de la señal de alta frecuencia (las pequeñas oscilaciones), se obtiene \\(f\\) = {@ta{X}_fc@}.",
  "osc.genfb_q2_retard": "P2 Retardo temporal:",
