  "diff.info_fente_simple_ecran": "Ranura única, medición directa en la imagen. El alumno desplaza el retículo sobre las manchas para medir la anchura l de la mancha central y, a continuación, deduce el valor de lambda.",
  "diff.info_fente_simple_capteur": "Ranura única, medición con sensor. Se muestra la figura y se añade un sensor que registra la intensidad I(y) = sinc²(beta); el alumno mide l en esta curva.",
  "diff.info_fente_double_ecran": "Dos rendijas, medición directa en el patrón de franjas (envolvente de difracción sin² x interferencias cos²). El alumno mide la distancia entre franjas i y la anchura l de la mancha central.",
  "diff.info_fente_double_capteur": "Dos rendijas, medición con el sensor. Se muestra el patrón de franjas y se añade una curva de intensidad I(y) = sinc²(alfa) x cos²(beta) para la medición.",
  "diff.info_young_ecran": "Agujeros de Young, medición directa en la figura 2D (mancha de Airy × cos²). El alumno desplaza el retículo sobre los anillos o franjas para medir la distancia entre franjas i.",
  "diff.info_young_capteur": "Agujeros de Young, medición en el sensor. Se muestra la figura en 2D y se añade un corte en 1D de la intensidad a lo largo de un eje para la medición en el sensor.",
  "diff.info_trou_circulaire_ecran": "Agujero circular, medición directa en la figura 2D (mancha de Airy). El alumno desplaza el retículo sobre el primer anillo oscuro para medir el radio r de la mancha central.",
  "diff.info_trou_circulaire_capteur": "Agujero circular, medición en el sensor. Se muestra la figura en 2D y se añade un corte radial en 1D de la intensidad para la medición en el sensor.",
  "diff.info_trou_carre_ecran": "Agujero cuadrado, medición directa en la figura 2D (mancha central cuadrada con forma de cruz). El alumno desplaza la retícula para medir la anchura l de la mancha central.",
  "diff.info_trou_carre_capteur": "Agujero cuadrado, medición con sensor. Se muestra la figura en 2D y se añade una curva I(y) procedente de un sensor para medir la anchura l de la mancha central.",
