  "geo.norme_ok_desc":     "La norma del vector se ha calculado y redondeado correctamente.",
  "geo.norme_racine_desc": "Has calculado la suma de los cuadrados de las coordenadas; eso es el <strong>cuadrado</strong> de la norma. Hay que calcular su raíz cuadrada.",
  "geo.norme_manhattan_desc":"Has sumado los valores absolutos de las coordenadas. En un sistema de coordenadas ortonormado, la norma es la raíz de la <strong>suma de los cuadrados</strong>.",
  "geo.norme_sub_title":   "¡Error de signo debajo de la raíz!",
  "geo.norme_sub_desc":    "Con Pitágoras, hay que <strong>sumar</strong> los cuadrados de las coordenadas, nunca restarlos.",
  "geo.norme_fallback_desc":"Aplica la fórmula de Pitágoras que se ha visto en clase: <br>\\(\\|\\vec{u}\\|=\\sqrt{x^2+y^2{zterm}}\\)",
  "geo.norme_correction_desc":"La norma de un vector \\(\\vec{u}\\) corresponde a su «longitud», calculada mediante la fórmula derivada del teorema de Pitágoras:<br><br>\n\\[\\|\\vec{u}\\|=\\sqrt{x^2+y^2{zterm1}}\\]<br>\n<strong>Aplicación:</strong><br><br>\n\\[\\|\\vec{u}\\|=\\sqrt{{ux}^2+{uy}^2{zterm2}}=\\sqrt{{suma}}\\approx{ta}\\]",

  "geo.pente_enonce1":     "En un sistema de coordenadas ortonormado del espacio, se considera la recta \\((d)\\) que pasa por \\(A\\left({xa}\\;;\\;{ya}\\;;\\;{za}\\right)\\) y cuyo vector director es \\(\\vec{u}\\begin{pmatrix}{a}\\\\{b}\\\\{c}\\end{pmatrix}\\).",
  "geo.pente_enonce2":     "<strong>1.</strong> Calcula la pendiente de la recta \\((d)\\), es decir, la pendiente de su proyección ortogonal en el plano horizontal \\((O;\\vec{i},\\vec{j})\\).",
  "geo.pente_hint_desc":   "<em>Introduce el resultado en forma de fracción exacta (p. ej., 3/2 o -4/5).</em>",
  "geo.pente_lbl":         "\\(p=\\)",
  "geo.pente_ok_desc":     "Has identificado correctamente que la pendiente corresponde a la relación entre las variaciones de \\(y\\) y las de \\(x\\).",
  "geo.pente_inv_title":   "¡Fracción invertida!",
  "geo.pente_inv_desc":    "Has calculado \\(\\frac{a}{b}\\) en lugar de \\(\\frac{b}{a}\\). La pendiente es siempre la elevación (\\(\\Delta y\\)) dividida por el avance horizontal (\\(\\Delta x\\)).",
  "geo.pente_z_title":     "¡Qué mal componente!",
  "geo.pente_z_desc":      "Has utilizado la coordenada \\(z\\) en lugar de \\(y\\). La pendiente en el plano horizontal se calcula únicamente con \\(x\\) e \\(y\\): \\(\\frac{b}{a}\\).",
  "geo.pente_moins_desc":  "El cálculo de los numeradores y denominadores es correcto, pero el signo final es incorrecto.",
  "geo.pente_fallback_desc":"La pendiente es igual a la relación entre la componente en \\(y\\) y la componente en \\(x\\) del vector director: <br>\\(p=\\frac{b}{a}\\)",
  "geo.pente_correction_desc":"El plano horizontal \\((O;\\vec{i},\\vec{j})\\) es el plano \\((xOy)\\). La proyección de \\((d)\\) en este plano es una recta en 2D cuyo coeficiente director es la pendiente buscada.<br><br>\nRepresentación paramétrica de \\((d)\\): \\(x={xa}+{a}t\\), \\(y={ya}+{b}t\\), \\(z={za}+{c}t\\).<br><br>\nEl coeficiente director (la pendiente) es, por tanto, el cociente de las coordenadas del vector director:<br><br>\n\\[p=\\frac{{b}}{{a}}={ta}\\]\n<em style=\"color:#64748b;\">Observación: la componente en \\(z\\) ({c}) no interviene en el cálculo de la pendiente «2D» de la recta.</em>",

  "geo.ordonnee_enonce1":  "Sea \\((d)\\) la recta cuya ecuación cartesiana es \\({eq}=0\\).",
  "geo.ordonnee_enonce2":  "<strong>1.</strong> Hallar la ordenada en el origen de la recta \\((d)\\).",
  "geo.ordonnee_hint_desc":"<em>Introduce el valor exacto (p. ej., 3/2 o -4).</em>",
  "geo.ordonnee_lbl":      "La ordenada en el origen es:",
  "geo.ordonnee_ok_desc":  "Es, efectivamente, el valor de \\(y\\) cuando \\(x=0\\).",
  "geo.ordonnee_const_title":"¡Confusión con la constante!",
  "geo.ordonnee_const_desc":"Has dado el valor de \\(c\\). Aquí hay que aislar \\(y\\) para hallar la ordenada, o bien poner \\(x=0\\).",
  "geo.ordonnee_sansmoins_desc":"Has calculado \\(\\frac{c}{b}\\). Al aislar \\(y\\), no olvides que el signo menos pasa al numerador: \\(y=\\frac{-c}{b}\\).",
  "geo.ordonnee_pente_title":"¡Confusión entre la pendiente y la ordenada!",
  "geo.ordonnee_pente_desc":"Has calculado el coeficiente director \\(-\\frac{a}{b}\\). La ordenada en el origen es el punto en el que la recta corta el eje vertical (cuando \\(x=0\\)).",
  "geo.ordonnee_axe_title": "¡Eje incorrecto!",
  "geo.ordonnee_axe_desc": "Has calculado la abscisa en el origen (cuando \\(y=0\\)). Se te pide la ordenada en el origen, es decir, el valor de \\(y\\) cuando \\(x=0\\).",
  "geo.ordonnee_fallback_desc":"Para hallar la ordenada en el origen, hay que sustituir \\(x\\) por \\(0\\) en la ecuación y resolverla respecto a \\(y\\).",
  "geo.ordonnee_correction_desc":"La ordenada en el origen corresponde al valor de \\(y\\) cuando la recta corta el eje de las ordenadas, es decir, cuando \\(x=0\\).<br><br>\nSustituimos \\(x\\) por \\(0\\) en la ecuación \\({eq}=0\\) :<br><br>\n\\[{a}(0)+{b}y+{c}=0\\]\n\\[{b}y+{c}=0\\implies{b}y=-{c}\\implica que y = \frac{-c}{b}\\]\n\\[y = ta\\]<br>\nPor lo tanto, la ordenada en el origen de la recta es {ta}.",

  "geo.aire_enonce1":      "{punto de referencia}, consideremos los puntos \\(A{A}\\), \\(B{B}\\) y \\(C{C}\\).",
  "geo.aire_enonce2":      "<strong>1.</strong> Calcula el área del triángulo \\(ABC\\). <em>(Redondea el resultado a \\(10^{-2}\\).)</em>",
  "geo.aire_lbl":          "\\(\\mathcal{A}(ABC)=\\)",
  "geo.aire_ok_desc":      "El área del triángulo se ha calculado correctamente.",
  "geo.aire_para_title":   "¡Área del paralelogramo!",
  "geo.aire_para_desc":    "Has calculado el producto escalar \\(\\vec{AB}\\times\\vec{AC}\\), el área del paralelogramo. Un triángulo representa la <strong>mitad</strong> de este.",
  "geo.aire_norac_desc":   "Has calculado \\(\\frac{x^2+y^2+z^2}{2}\\). La norma de un vector es \\(\\sqrt{x^2+y^2+z^2}\\), no hay que olvidar esa raíz.",
  "geo.aire_2d_title":     "¡Cálculo en 2D!",
  "geo.aire_2d_desc":      "Has omitido la coordenada en \\(z\\). En 3D, hay que utilizar el <strong>producto vectorial</strong> en el espacio para tener en cuenta la profundidad.",
  "geo.aire_fallback_3d_desc":"Aplica la fórmula:<br>\\(\\mathcal{A}=\\frac{1}{2}\\|\\vec{AB}\\times\\vec{AC}\\|\\)<br>sin olvidar el producto vectorial completo (3 coordenadas) y la raíz cuadrada para la norma.",
  "geo.aire_fallback_2d_desc":"Aplica la fórmula del área de un triángulo a partir de las coordenadas:<br>\\(\\mathcal{A}=\\frac{1}{2}|x_{\\vec{AB}}y_{\\vec{AC}}-y_{\\vec{AB}}x_{\\vec{AC}}|\\)",
  "geo.aire_correction_3d":"En el espacio, el área de un triángulo es la mitad de la norma del producto vectorial de dos de sus lados:<br><br>\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}\\|\\vec{AB}\\times\\vec{AC}\\|\\]<br>\n<strong>1. Vectores:</strong> \\(\\vec{AB}\\begin{pmatrix}{ux}\\\\{uy}\\\\{uz}\\end{pmatrix}\\), \\(\\vec{AC}\\begin{pmatrix}{vx}\\\\{vy}\\\\{vz}\\end{pmatrix}\\)<br><br>\n<strong>2. Producto vectorial:</strong> \\(\\vec{AB}\\times\\vec{AC}\\begin{pmatrix}{cx}\\\\{cy}\\\\{cz}\\end{pmatrix}\\)<br><br>\n<strong>3. Norma y área:</strong><br>\n\\[\\|\\vec{AB}\\×\\vec{AC}\\|=\\sqrt{{cx}^2+{cy}^2+{cz}^2}\\approx{sqrt_arr}\\]\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}\\times{sqrt_arr}\\approx{ta}\\]",
  "geo.aire_correction_2d":"En el plano, el área de un triángulo se calcula a partir de los vectores \\(\\vec{AB}\\) y \\(\\vec{AC}\\):<br><br>\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}|x_{\\vec{AB}}\\,y_{\\vec{AC}}-y_{\\vec{AB}}\\,x_{\\vec{AC}}|\\]<br>\n<strong>1. Vectores:</strong> \\(\\vec{AB}\\begin{pmatrix}{ux}\\\\{uy}\\end{pmatrix}\\), \\(\\vec{AC}\\begin{pmatrix}{vx}\\\\{vy}\\end{pmatrix}\\)<br><br>\n<strong>2. Cálculo:</strong><br>\n\\[\\mathcal{A}(ABC)=\\frac{1}{2}|{ux}\\times{vy}-{uy}\\times{vx}|\\approx{ta}\\]",

