  "bn.largeur_fixe_hint":   "Si se ha introducido, la respuesta esperada se completa con ceros a la izquierda hasta alcanzar exactamente ese número de dígitos (por ejemplo: 4 → «00000100» en 8 bits).",
  "bn.valeur_convertir_lbl":"Valor a convertir",
  "bn.value_mode_fixe":     "Fijo",
  "bn.value_mode_aleatoire":"Aleatorio (Moodle)",
  "bn.value_base_depart":   "Valor expresado en la base inicial",
  "bn.value_base_arrivee":  "Valor expresado en base de llegada",
  "bn.borne_min_lbl":       "Valor mínimo (decimal)",
  "bn.borne_max_lbl":       "Valor máximo (decimal)",
  "bn.fbgen_auto_desc":     "La corrección de la conversión es automática. Este campo permite añadir un comentario didáctico complementario, que se muestra además de la solución esperada.",
  "bn.basename_binaire":     "binario",
  "bn.basename_octal":       "octal",
  "bn.basename_decimal":     "decimal",
  "bn.basename_hexadecimal": "hexadecimal",
  "bn.basename_generic":     "base {b}",
  "bn.syntaxhint_fallback":  "Calificación esperada: véanse las instrucciones anteriores.",
  "bn.banniere":             "Numeración — Conversión a {base}",
  "bn.base_badge":           "Base {toBase}",
  "bn.unit_bit":             "bit",
  "bn.unit_chiffre":         "cifra",
  "bn.frompart":             " (base {fromBase})",
  "bn.widthpart":            " en {width} {unit}",
  "bn.default_question":     "Convertir <strong>{val}</strong>{fromPart} en <strong>{toName}</strong> (base {toBase}){widthPart}.",
  "bn.fbgen_to_decimal":        "Para convertir {val} (base {fromBase}) al sistema decimal, se multiplica cada dígito por la potencia de {fromBase} correspondiente a su posición y, a continuación, se suman todos los resultados.",
  "bn.fbgen_to_decimal_result": "{val}<sub>{fromBase}</sub> = {valDec}<sub>10</sub>",
  "bn.fbgen_to_base":           "Para convertir {val} a la base {toBase}, se realizan divisiones sucesivas por {toBase}. El resultado se lee remontando por los restos (del último al primero).",
  "bn.fbgen_to_base_result":    "{val}<sub>{fromBase}</sub> = {valDst}<sub>{toBase}</sub>",
  "bn.fb_ok_desc":           "La conversión es correcta.",
  "bn.fb_wrong_resultat":    "El resultado esperado era <code>{val}</code>.",
  "bn.fb_err_base_title":    "Error básico.",
  "bn.fb_err_base_desc":     "Has hecho el cálculo como si el número fuera en base 10. Es un número en <strong>base {fromBase}</strong>, ¡hay que utilizar potencias de {fromBase}!",
  "bn.fb_err_sens_title":    "Error en el sentido de lectura.",
  "bn.fb_err_sens_desc":     "El número situado más a la derecha siempre es {fromBase}<sup>0</sup>, el siguiente hacia la izquierda es {fromBase}<sup>1</sup>, etc.",
  "bn.fb_format_incorrect":  "Formato incorrecto.",
  "bn.fb_err_espaces_desc":  "Tu respuesta contiene espacios. Escribe la respuesta sin espacios.",
  "bn.fb_err_prefixe_desc":  "No añadas ningún prefijo. Escribe solo la secuencia de caracteres.",
  "bn.fb_err_lettres_desc":  "La base {toBase} no contiene letras. Introduce solo números.",
  "bn.fb_presque_correct":   "Casi correcto.",
  "bn.fb_err_minuscules_desc": "El resultado parece correcto, pero las letras deben estar en <strong>mayúsculas</strong>.",
  "bn.fb_err_zeros_desc":    "En la notación estándar, no se pone un cero al principio. Elimina el cero o los ceros innecesarios.",
  "bn.fb_err_recopie_desc":  "Has copiado el valor inicial. La consigna pide que lo conviertas a la base {toBase}.",
  "bn.fb_err_lecture_title": "Error de lectura.",
  "bn.fb_err_lecture_desc":  "¡Has leído los restos al revés! Hay que leer los restos desde la <b>última</b> división hasta la <b>primera</b>.",
  "bn.fb_err_carac_title":   "Caracteres no válidos.",
  "bn.fb_err_carac_desc":    "Un número en base {toBase} solo debe contener los símbolos permitidos en esa base.",
  "bn.syntax_only_integer": "Notación esperada: solo el número entero resultante (sin espacios).",
  "bn.syntax_width_note": " Respuesta esperada con exactamente <strong>{width}</strong> cifras: complete con ceros a la izquierda si es necesario.",
  "bn.syntax_c_bin": "Notación esperada: prefijo 0b seguido de dígitos binarios en MAYÚSCULAS, sin espacios (ej: 0b101010).",
  "bn.syntax_c_oct": "Notación esperada: prefijo 0o seguido de dígitos octales, sin espacios (ej: 0o17).",
  "bn.syntax_c_hex": "Notación esperada: prefijo 0x seguido de dígitos hexadecimales en MAYÚSCULAS, sin espacios (ej: 0x1A).",
  "bn.syntax_std_width_upper": "Notación esperada: cifras en MAYÚSCULAS, sin espacios, sin prefijo.",
  "bn.syntax_std_width": "Notación esperada: cifras sin espacios, sin prefijo.",
  "bn.syntax_upper_nowidth": "Notación esperada: cifras en MAYÚSCULAS, sin espacios, sin prefijo, sin cero inicial innecesario.",
  "bn.syntax_nowidth": "Notación esperada: solo cifras, sin espacios, sin prefijo, sin cero inicial innecesario.",
  "bn.lbl_valeur_bornes_decimal": "Valor a convertir (límites en decimal)",
  "bn.lbl_valeur_chiffres_base": "Valor a convertir (cifras en base {base})",
  "bn.warn_notation_c_title": "La notación C (0b/0o/0x) solo está disponible para las bases 2, 8 y 16. Cambie a notación de sufijo.",
