  "opt.info_lentille_convergente": "✏️ El alumno traza al menos dos de los tres rayos particulares desde B con la barra de herramientas (rayo 2 clics, rayo // eje, rayo paralelo 3 clics), y luego construye el punto B' por intersección de los rayos emergentes. El estado real/virtual de cada tramo se corrige automáticamente.",
  "opt.info_lentille_divergente": "✏️ Como en la lente convergente, pero la imagen es <strong>siempre virtual</strong>: los rayos emergentes divergen tras la lente y deben prolongarse hacia atrás (líneas discontinuas) para construir B'.",
  "opt.info_miroir_plan": "✏️ El alumno traza los dos rayos notables desde B (incidencia normal y un rayo que llega a S), los refleja en el espejo plano y luego construye B' por intersección de los rayos reflejados prolongados. La imagen es <strong>siempre virtual y del mismo tamaño</strong> que el objeto.",
  "opt.info_miroir_concave": "✏️ El alumno traza al menos dos de los cuatro rayos notables desde B (// eje, por C, por F, hacia S), los refleja en el espejo y luego construye B' por intersección de los rayos reflejados. Según la posición del objeto (SA &lt; f o SA &gt; f), la imagen es virtual o real — el estado real/virtual esperado de cada tramo se corrige automáticamente.",
  "opt.info_miroir_convexe": "✏️ Como en el espejo cóncavo, pero el foco F y el centro C son <strong>virtuales</strong> (detrás del espejo): la imagen obtenida es siempre virtual, sea cual sea la posición del objeto.",
  "opt.info_lunette_galilee": "✏️ El alumno construye cuatro rayos notables: dos rayos incidentes paralelos (uno por el centro del objetivo) que convergen en B&#8321; en el plano focal común, luego dos rayos desde B&#8321; hacia el ocular, que salen paralelos (sistema afocal, imagen en el infinito). El punto B&#8321; se construye con la herramienta «Intersección».",
  "opt.info_telescope_newton": "✏️ El alumno construye dos rayos incidentes paralelos inclinados un ángulo θ (uno que toca el vértice S del espejo primario, el otro desplazado h) y sus rayos reflejados correspondientes (usar «Simétrico / eje» para el rayo reflejado en el vértice), que convergen en el punto imagen B&#8321; en el plano focal del espejo. El punto B&#8321; se construye con la herramienta «Intersección».",
  "opt.info_microscope": "✏️ El alumno traza al menos dos de los tres rayos notables desde B a través del objetivo L&#8321;, que convergen en B&#8321; (imagen real intermedia, construida con «Intersección»), y luego los dos rayos desde B&#8321; a través del ocular L&#8322;, colocado de modo que B&#8321; esté exactamente en su plano focal objeto (ajuste para un ojo normal): el haz emergente sale paralelo (imagen final en el infinito).",
